import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    c = [0] + [int(x) for x in data[1:1 + n]]
    f = [0] * (n + 2)
    d = deque()
    for i in range(n, 0, -1):
        if i + 1 <= n:
            while d and f[d[-1]] >= f[i + 1]:
                d.pop()
            d.append(i + 1)
        if 2 * i >= n:
            f[i] = c[i]
        else:
            while d[0] > 2 * i + 1:
                d.popleft()
            f[i] = c[i] + f[d[0]]
    print(f[1])

main()

