if n <= 16:
    best = None
    for mask in range(1, 1 << n):
        covered = [False] * (n + 2)
        cost = 0
        for i in range(1, n + 1):
            if mask >> (i - 1) & 1:
                cost += c[i]
                for j in range(i, min(2 * i, n) + 1):
                    covered[j] = True
        if all(covered[1:n + 1]) and (best is None or cost < best):
            best = cost
    print(best)
else:
    f = [0] * (n + 2)
    for i in range(n, 0, -1):
        if 2 * i >= n:
            f[i] = c[i]
        else:
            f[i] = c[i] + min(f[j] for j in range(i + 1, 2 * i + 2))
    print(f[1])

