def gen(rng):
    def fmt(c):
        return str(len(c)) + '\n' + ' '.join(map(str, c))
    tests = [fmt([7]), fmt([5, 9]), fmt([3, 1, 2]), fmt([4, 5, 1, 2, 8]), fmt([1, 10, 1, 1]),
             fmt([1] * 12), fmt([10 ** 9] * 9), fmt([5, 1, 1, 1, 1, 1, 1, 1])]
    for n in (2, 3, 4, 5, 6, 7, 8, 10, 12, 14):
        for _ in range(2):
            tests.append(fmt([rng.randint(1, 20) for _ in range(n)]))
    for n in (6, 9, 12):
        tests.append(fmt([rng.randint(1, 3) for _ in range(n)]))
    tests.append(fmt([rng.randint(1000, 10 ** 9) for _ in range(300)]))
    tests.append(fmt([rng.randint(1, 10 ** 9) for _ in range(3000)]))
    tests.append(fmt(sorted(rng.randint(1, 10 ** 9) for _ in range(5000))))
    N = 100000
    tests.append(fmt([rng.randint(1, 10 ** 9) for _ in range(N)]))
    tests.append(fmt([rng.randint(1, 10) for _ in range(N)]))
    tests.append(fmt(sorted((rng.randint(1, 10 ** 9) for _ in range(N)), reverse=True)))
    tests.append(fmt([10 ** 9] * N))
    return tests

